from pathlib import Path
from html.parser import HTMLParser
from urllib.parse import urljoin, urlsplit
import hashlib, json, re

source_url = 'https://www.nasa.gov/prizes-challenges-and-crowdsourcing/'
source = Path('products/services/public-challenge-fixed-prize/raw/nasa-prizes.html')
class Links(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.current = None
        self.links = {}
    def handle_starttag(self, tag, attrs):
        if tag == 'a':
            self.current = (dict(attrs).get('href') or '', [])
    def handle_data(self, data):
        if self.current is not None:
            self.current[1].append(data)
    def handle_endtag(self, tag):
        if tag != 'a' or self.current is None:
            return
        href, parts = self.current
        self.current = None
        label = ' '.join(' '.join(parts).split())
        url = urljoin(source_url, href)
        if href and not href.startswith('#') and urlsplit(url).scheme == 'https' and url != source_url and label and re.search(r'challenge|prize|competition|centennial|crowdsourc', label, re.I):
            self.links.setdefault(url, label)

raw = source.read_bytes()
parser = Links()
parser.feed(raw.decode('utf-8', errors='replace'))
result = {'source_url': source_url, 'sha256': hashlib.sha256(raw).hexdigest(), 'scope': 'Link labels and targets from the saved NASA landing page. Live status, original rules, entrant eligibility and payout remain unverified.', 'matches': len(parser.links), 'links': [{'label': label, 'url': url} for url, label in list(parser.links.items())[:30]]}
out = Path('products/services/public-challenge-fixed-prize/nasa-rule-pointers.json')
out.parent.mkdir(parents=True, exist_ok=True)
out.write_text(json.dumps(result, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
print(out.read_text(encoding='utf-8'))
